<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useQuasar } from 'quasar'
import { telemetryApi, management, inventoryPage } from '../api'
import { t, locale } from '../i18n'
import { routeHash } from '../routes'
import PageHeader from './PageHeader.vue'
import PageActions from './PageActions.vue'
import { containerStateText, containerSummary, containerGroup, memoryPercent, diskPercent, timestamp } from '../telemetry-summary'
import TelemetryTrend from './TelemetryTrend.vue'
const props=defineProps({canEdit:Boolean,initialServer:{type:String,default:null}})
const q=useQuasar(), servers=ref([]), server=ref(props.initialServer), currentContainers=ref([]), agents=ref([]), samples=ref([]), latest=ref(null), days=ref(1/4), busy=ref(false), error=ref(''), secret=ref(''), confirming=ref<false | 'provision' | 'revoke'>(false), now=ref(Date.now()), settings=ref(false), settingsBusy=ref(false), rankingMetric=ref('cpu')
let generation=0, timer=null, lookupGeneration=0
const options=computed(()=>{const list=servers.value.map(s=>({label:s.name || s.ip || s.id,value:s.id}));if(latest.value && !list.some(s=>s.value===latest.value.id))list.unshift({label:latest.value.name || latest.value.ip,value:latest.value.id});return list})
const agent=computed(()=>agents.value.find(a=>a.server===server.value))
const last=computed(()=>latest.value?.telemetry || null)
const hostOnly=computed(()=>last.value?.collection_mode==='host')
const operatingSystem=computed(()=>{const os=last.value?.host?.operating_system;return os?[os.pretty_name || [os.name,os.version_id].filter(Boolean).join(' '),os.architecture,os.kernel].filter(Boolean).join(' · '):''})
const windowsHost=computed(()=>last.value?.host?.operating_system?.family==='windows' || last.value?.host?.os==='windows')
const sessionLabel=value=>t(value===true?'RDP session active':value===false?'No active RDP session':'unknown')
const sessionRows=computed(()=>samples.value.map(s=>({observed_at:s.observed_at,active:s.payload?.host?.rdp_session_active})).sort((a,b)=>timestamp(b.observed_at)-timestamp(a.observed_at)))
const sessionColumns=computed(()=>[{name:'observed_at',label:t('Collected at'),field:'observed_at',format:date,align:'left' as const},{name:'active',label:t('RDP session'),field:'active',format:sessionLabel,align:'left' as const}])
const stale=computed(()=>!!last.value?.observed_at && now.value-timestamp(last.value.observed_at)>900000)
const status=computed(()=>!last.value?.observed_at?'No telemetry':stale.value?'No communication':last.value.state || 'unknown')
const statusColor=computed(()=>status.value==='healthy'?'positive':status.value==='degraded'?'warning':'grey')
const rangeOptions=computed(()=>[{label:t('1 hour'),value:1/24},{label:t('6 hours'),value:1/4},{label:t('24 hours'),value:1},{label:t('7 days'),value:7}])
const start=computed(()=>now.value-days.value*86400000)
const date=v=>Number.isFinite(timestamp(v))?new Date(timestamp(v)).toLocaleString(locale.value):'—'
const pct=v=>Number.isFinite(v)?`${v.toFixed(1)}%`:'—'
const bytes=v=>Number.isFinite(v)?`${(v/1024**3).toFixed(1)} GiB`:'—'
const counts=computed(()=>containerSummary(currentContainers.value))
const total=computed(()=>currentContainers.value.length)
const runningPercent=computed(()=>total.value?counts.value.running/total.value*100:0)
const attentionEnd=computed(()=>total.value?(counts.value.running+counts.value.attention)/total.value*100:0)
const disks=computed(()=>(last.value?.host?.disks || []).map(d=>({...d,used:diskPercent(d)})))
const diskMax=computed(()=>{const known=disks.value.map(d=>d.used).filter(Number.isFinite);return known.length?Math.max(...known):null})
const metrics=computed(()=>[
 {label:'CPU',value:pct(last.value?.host?.cpu_percent),icon:'memory',tone:last.value?.host?.cpu_percent>=90?'negative':'primary',caption:t('Host usage')},
 {label:t('Memory'),value:pct(memoryPercent(last.value?.host)),icon:'storage',tone:memoryPercent(last.value?.host)>=90?'warning':'primary',caption:bytes(last.value?.host?.memory_available_bytes)+' '+t('available')},
 {label:t('Disk usage'),value:pct(diskMax.value),icon:'dns',tone:diskMax.value>=90?'warning':'primary',caption:t('Most used filesystem')},
 {label:t(hostOnly.value?'Uptime':'Containers'),value:hostOnly.value?((last.value?.host?.uptime_seconds || 0)/86400).toFixed(1)+' d':last.value?.observed_at?`${counts.value.running} / ${total.value}`:'—',icon:hostOnly.value?'timer':'layers',tone:counts.value.attention?'warning':'positive',caption:t(hostOnly.value?'Host usage':'Healthy')}
])
const notices=computed(()=>[...(last.value?.errors || []),...(last.value?.warnings || [])])
const attention=computed(()=>currentContainers.value.filter(r=>containerGroup(r)==='attention').map(r=>({...r,state:r.telemetry.state,health:r.telemetry.health || '—'})))
function cellValue(column,row){return typeof column.field==='function'?column.field(row):row[column.field]}
const columns=computed(()=>[{name:'name',label:t('Container'),field:'name',align:'left' as const,sortable:true},{name:'state',label:t('State'),field:'state',align:'left' as const},{name:'health',label:'Healthcheck',field:'health',align:'left' as const}])
const ranking=computed(()=>currentContainers.value.filter(r=>Number.isFinite(r.telemetry?.[rankingMetric.value==='cpu'?'cpu_percent':'memory_bytes'])).map(r=>({id:r.id,name:r.name,value:r.telemetry[rankingMetric.value==='cpu'?'cpu_percent':'memory_bytes']})).sort((a,b)=>b.value-a.value).slice(0,5))
const rankingMax=computed(()=>Math.max(1,...ranking.value.map(r=>r.value)))
const serverLink=computed(()=>routeHash({view:'projects',server:server.value}))
const containerLink=computed(()=>routeHash({view:'containers',server:server.value}))
const installLink=computed(()=>`#/servers/${server.value}/agent-installation`)
async function lookup(value,done){const id=++lookupGeneration;try{const result=await inventoryPage('servers',{search:value,perPage:50,serverType:'VPS'});if(id===lookupGeneration)done(()=>servers.value=result.items.filter(s=>s.type==='VPS'));else done(()=>{})}catch{done(()=>{})}}
function chooseServer(value){if(value)window.location.hash=routeHash({view:'telemetry',server:value})}
async function refresh(){
 const id=++generation,selected=server.value
 if(!selected)return
 busy.value=true;error.value=''
 try{const [record,history,containers]=await Promise.all([management.get('servers',selected),telemetryApi.trends(selected,days.value),telemetryApi.containers(selected)]);if(id!==generation)return;latest.value=record;currentContainers.value=containers;samples.value=history;now.value=Date.now()}
 catch{if(id===generation)error.value=t('Unable to load telemetry')}
 finally{if(id===generation)busy.value=false}
}
async function loadAgents(){settingsBusy.value=true;try{const keys=await telemetryApi.agents();agents.value=keys.items}catch{error.value=t('Unable to load telemetry')}finally{settingsBusy.value=false}}
async function provision(){settingsBusy.value=true;secret.value='';try{const r=await telemetryApi.provision(server.value);secret.value=r.token;confirming.value=false;await loadAgents()}catch{error.value=t('Unable to create agent credential')}finally{settingsBusy.value=false}}
async function revoke(){settingsBusy.value=true;try{await telemetryApi.revoke(agent.value.id);secret.value='';confirming.value=false;await loadAgents()}catch{error.value=t('Unable to revoke agent credential')}finally{settingsBusy.value=false}}
async function copyIp(){try{await navigator.clipboard.writeText(latest.value.ip);q.notify({message:t('Copied to clipboard'),type:'positive',position:'bottom-right',timeout:1500})}catch{q.notify({message:t('Unable to copy. Select the text manually.'),type:'negative'})}}
async function copySecret(){try{await navigator.clipboard.writeText(secret.value);q.notify({message:t('Copied to clipboard'),color:'positive'})}catch{error.value=t('Unable to copy')}}
watch(days,()=>refresh())
onMounted(async()=>{if(server.value)refresh();else try{const result=await inventoryPage('servers',{perPage:50,serverType:'VPS'});servers.value=result.items.filter(s=>s.type==='VPS');if(servers.value[0])chooseServer(servers.value[0].id)}catch{error.value=t('Unable to load telemetry')};timer=setInterval(()=>{now.value=Date.now();if(server.value && !busy.value && !document.hidden)refresh()},60000)})
onUnmounted(()=>{generation++;lookupGeneration++;clearInterval(timer)})
</script>

<template>
<q-page class="q-pa-md inventory-page telemetry-page">
 <PageHeader :title="t('Telemetry')" :breadcrumbs="server ? [{label:t('Servers'),href:'#/servers'},{label:latest?.name || server,href:serverLink}] : undefined" />
 <q-banner v-if="error" role="alert" class="q-mb-md bg-negative text-white">{{error}}</q-banner>
 <q-card flat bordered class="telemetry-toolbar q-mb-md">
  <div class="telemetry-filters"><q-select :model-value="server" @update:model-value="chooseServer" :options="options" use-input fill-input hide-selected @filter="lookup" input-debounce="300" emit-value map-options outlined dense :label="t('Server')" class="telemetry-server"/><q-select v-model="days" :options="rangeOptions" emit-value map-options outlined dense :label="t('History')" class="telemetry-range"/></div>
  <div class="telemetry-actions"><div v-if="latest" class="server-summary"><div><strong>{{latest.name}}</strong><span class="telemetry-ip">{{latest.ip || '—'}}<q-btn v-if="latest.ip" flat dense round size="sm" icon="content_copy" :aria-label="t('Copy IP')" @click="copyIp"><q-tooltip>{{t('Copy IP')}}</q-tooltip></q-btn></span><span v-if="operatingSystem" :title="t('Operating system')">{{operatingSystem}}</span></div><div class="telemetry-contact"><q-badge rounded :color="statusColor">{{t(status)}}</q-badge><span>{{t('Collected at')}}: {{date(last?.observed_at)}}</span><q-tooltip>{{t('Collection runs every five minutes')}}</q-tooltip></div></div><PageActions :actions="[{label:t('Refresh'),icon:'refresh',loading:busy,onClick:refresh}]" /></div>
 </q-card>
 <q-card v-if="!server && !busy" flat bordered class="telemetry-empty"><q-icon name="dns" size="36px" color="primary"/><h2>{{t('No servers available')}}</h2><q-btn flat no-caps color="primary" :label="t('Servers')" href="#/servers"/></q-card>
 <template v-if="server">
  <q-banner v-if="stale" class="telemetry-warning q-mb-md" rounded><template #avatar><q-icon name="schedule"/></template>{{t('Showing the last known condition')}} · {{t('No communication')}}</q-banner>
  <q-card v-if="!busy && latest && !last?.observed_at" flat bordered class="telemetry-empty q-mb-md"><q-icon name="monitor_heart" size="36px" color="primary"/><h2>{{t('No telemetry')}}</h2><p>{{t('Install the daemon to see live server metrics.')}}</p><q-btn v-if="canEdit" no-caps unelevated color="primary" icon="terminal" :label="t('Install daemon')" :href="installLink"/></q-card>
  <template v-else>
   <q-card flat bordered class="metric-strip q-mb-md"><div v-for="metric in metrics" :key="metric.label" class="metric-cell"><div class="metric-label"><q-icon :name="metric.icon" size="18px"/>{{metric.label}}</div><strong :class="'text-'+metric.tone">{{metric.value}}</strong><small>{{metric.caption}}</small></div></q-card>
   <q-card flat bordered class="q-mb-md"><div class="panel-heading"><div><h2>{{t('Resource history')}}</h2><p>{{t('Host CPU and memory in the selected period')}}</p></div><q-badge v-if="stale" outline color="warning">{{t('No communication')}}</q-badge></div><q-separator/><div class="trend-grid"><TelemetryTrend :samples="samples" metric="cpu" :start="start" :end="now" label="CPU" color="#6366f1"/><TelemetryTrend :samples="samples" metric="memory" :start="start" :end="now" :label="t('Memory')" color="#0d9488"/></div></q-card>
   <div class="telemetry-grid q-mb-md" :style="hostOnly?{gridTemplateColumns:'1fr'}:undefined">
    <q-card v-if="!hostOnly" flat bordered><div class="panel-heading"><div><h2>{{t('Container health')}}</h2><p>{{total}} {{t('containers')}}</p></div><q-btn flat no-caps color="primary" :label="t('View containers')" :href="containerLink"/></div><q-separator/><div class="container-health"><div class="health-ring" :style="{'--running':runningPercent+'%','--attention':attentionEnd+'%'}"><div><strong>{{counts.running}}</strong><small>{{t('Healthy')}}</small></div></div><div class="health-legend"><div><i class="bg-positive"/>{{t('Healthy')}}<strong>{{counts.running}}</strong></div><div><i class="bg-warning"/>{{t('Needs attention')}}<strong>{{counts.attention}}</strong></div><div><i class="bg-grey-5"/>{{t('No telemetry')}}<strong>{{counts.unknown}}</strong></div></div></div></q-card>
    <q-card flat bordered><div class="panel-heading"><div><h2>{{t('Disk usage')}}</h2><p>{{t('Used space by filesystem')}}</p></div></div><q-separator/><div class="disk-list"><div v-for="disk in disks" :key="disk.path"><div class="bar-heading"><strong>{{disk.path}}</strong><span>{{pct(disk.used)}}</span></div><q-linear-progress rounded size="7px" :value="(disk.used || 0)/100" :color="disk.used>=90?'warning':'primary'" track-color="grey-4"/><small>{{bytes(disk.total_bytes-disk.available_bytes)}} / {{bytes(disk.total_bytes)}}</small></div><p v-if="!disks.length" class="text-grey-6">{{t('No telemetry')}}</p></div></q-card>
   </div>
   <div v-if="!hostOnly" class="telemetry-grid q-mb-md">
    <q-card flat bordered><div class="panel-heading"><div><h2>{{t('Top consumers')}}</h2><p>{{t('Latest collected sample')}} · {{t('Top 5 containers')}}</p></div><q-btn-toggle v-model="rankingMetric" dense no-caps unelevated toggle-color="primary" :options="[{label:'CPU',value:'cpu'},{label:t('Memory'),value:'memory'}]"/></div><q-separator/><div class="consumer-list"><div v-for="item in ranking" :key="item.id"><div class="bar-heading"><strong :title="item.name">{{item.name}}</strong><span>{{rankingMetric==='cpu'?pct(item.value):bytes(item.value)}}</span></div><q-linear-progress rounded size="6px" :value="item.value/rankingMax" :color="rankingMetric==='cpu'?'primary':'teal'" track-color="grey-4"/></div><p v-if="!ranking.length" class="text-grey-6">{{t('No telemetry')}}</p></div></q-card>
    <q-card flat bordered><div class="panel-heading"><div><h2>{{t('Needs attention')}}</h2><p>{{t('Stopped, missing or unhealthy containers')}}</p></div><q-badge :color="counts.attention?'warning':'positive'">{{counts.attention}}</q-badge></div><q-separator/><q-table flat :grid="q.screen.lt.md" :rows="attention" :columns="columns" row-key="id" :pagination="{rowsPerPage:5}" :rows-per-page-options="[5,10]" :hide-bottom="attention.length<=5" class="inventory-table attention-table"><template #item="scope"><q-card flat bordered class="telemetry-mobile-card"><q-card-section><strong>{{scope.row.name}}</strong><dl><div><dt>{{t('State')}}</dt><dd>{{t(containerStateText(scope.row))}}</dd></div><div><dt>Healthcheck</dt><dd>{{t(scope.row.health)}}</dd></div></dl></q-card-section></q-card></template><template #body-cell-health="scope"><q-td :props="scope">{{t(scope.row.health)}}</q-td></template><template #body-cell-state="scope"><q-td :props="scope"><q-badge outline color="warning">{{t(containerStateText(scope.row))}}</q-badge></q-td></template><template #no-data><div class="attention-clear"><q-icon name="check_circle" color="positive" size="22px"/><span>{{total?counts.unknown===total?t('No telemetry'):t('No containers requiring attention'):t('No containers inventoried')}}</span></div></template></q-table></q-card>
   </div>
   <q-card v-if="windowsHost" flat bordered class="q-mb-md"><div class="panel-heading"><div><h2>{{t('RDP session')}}</h2><p>{{sessionLabel(stale?null:last?.host?.rdp_session_active)}}</p><p>{{t('Session state sampled every five minutes; not the exact login time.')}}</p></div></div><q-separator/><q-table class="session-table" flat :grid="q.screen.lt.md" :rows="sessionRows" :columns="sessionColumns" row-key="observed_at" :pagination="{rowsPerPage:10}" :rows-per-page-options="[10,25,50]"><template #item="scope"><q-card flat bordered class="telemetry-mobile-card"><q-card-section><dl><div v-for="column in sessionColumns" :key="column.name"><dt>{{column.label}}</dt><dd>{{cellValue(column,scope.row)}}</dd></div></dl></q-card-section></q-card></template></q-table></q-card>
   <q-expansion-item v-if="notices.length" icon="info" :label="t('Collection notices')+' ('+notices.length+')'" class="telemetry-expansion q-mb-md"><q-list separator><q-item v-for="notice in notices" :key="notice"><q-item-section>{{notice}}</q-item-section></q-item></q-list></q-expansion-item>
  </template>
  <q-expansion-item v-if="canEdit" v-model="settings" icon="settings" :label="t('Agent settings')" class="telemetry-expansion" @show="loadAgents"><div class="q-pa-md"><div class="row items-center justify-between q-gutter-md"><div><p class="q-mb-xs">{{t('Agent version')}}: {{last?.agent_version || '—'}}</p><p class="text-grey-6 q-mb-none">{{t('This credential only accesses telemetry for this server')}}</p></div><q-btn flat no-caps color="primary" icon="terminal" :label="t('Install daemon')" :href="installLink"/></div><p v-if="agent" class="q-mt-md">{{agent.prefix}}…</p><div class="q-mt-sm"><PageActions :actions="[{label:t(agent?'Rotate credential':'Create credential'),outline:true,disable:settingsBusy,onClick:()=>confirming='provision'},...(agent?[{label:t('Revoke credential'),color:'negative',disable:settingsBusy,onClick:()=>confirming='revoke'}]:[])]" /></div>
   <q-banner v-if="confirming" class="q-mt-md telemetry-warning"><p>{{t('Existing agent credentials will stop working. Update the server configuration after rotation.')}}</p><div class="row q-gutter-sm"><q-btn flat no-caps :label="t('Cancel')" @click="confirming=false"/><q-btn unelevated no-caps color="primary" :label="t('Confirm')" :loading="settingsBusy" @click="confirming==='revoke'?revoke():provision()"/></div></q-banner>
   <q-banner v-if="secret" class="q-mt-md"><p>{{t('Copy this secret now. It will not be shown again.')}}</p><code class="agent-secret">{{secret}}</code><q-btn flat no-caps icon="content_copy" :label="t('Copy credential')" @click="copySecret"/></q-banner>
  </div></q-expansion-item>
 </template>
 <q-inner-loading :showing="busy && !latest"><q-spinner color="primary" size="36px"/></q-inner-loading>
</q-page>
</template>
<style scoped>
.telemetry-ip{display:inline-flex;align-items:center;gap:4px;white-space:nowrap}

.telemetry-toolbar{padding:16px;position:sticky;top:50px;z-index:5}.telemetry-actions{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin-top:16px}.telemetry-actions .server-summary{flex:1;margin-top:0;justify-content:flex-start;flex-wrap:wrap}.telemetry-actions .page-actions{margin-left:auto}.telemetry-contact{flex-wrap:wrap}.telemetry-filters{display:flex;gap:12px}.telemetry-server{width:360px;max-width:100%}.telemetry-range{width:180px}.server-summary{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-top:20px}.server-summary>div:first-child{display:flex;align-items:center;gap:12px}.server-summary strong{font-size:16px;font-weight:600}.server-summary span{font-size:12px;color:#71717a}.telemetry-contact{display:flex;align-items:center;gap:12px}.metric-strip{display:grid;grid-template-columns:repeat(4,1fr)}.metric-cell{padding:20px;border-right:1px solid rgba(127,127,127,.15)}.metric-cell:last-child{border:0}.metric-label{display:flex;align-items:center;gap:8px;font-size:12px;color:#71717a}.metric-cell>strong{display:block;font-size:28px;line-height:1.4;font-weight:600;margin:8px 0 2px;font-variant-numeric:tabular-nums}.metric-cell>small{font-size:11px;color:#71717a}.trend-grid,.telemetry-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.trend-grid{gap:0}.trend-grid>*+*{border-left:1px solid rgba(127,127,127,.15)}.telemetry-page .panel-heading h2{font-size:16px}.container-health{padding:24px;display:flex;gap:32px;align-items:center}.health-ring{width:126px;height:126px;flex-shrink:0;border-radius:50%;padding:10px;background:conic-gradient(var(--q-positive) 0 var(--running),var(--q-warning) var(--running) var(--attention),#e4e4e7 var(--attention) 100%)}.health-ring>div{height:100%;background:white;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center}.health-ring strong{font-size:28px;font-weight:600}.health-ring small{font-size:11px;color:#71717a}.health-legend{flex:1;min-width:0}.health-legend>div{display:flex;gap:8px;align-items:center;font-size:12px;margin:14px 0}.health-legend i{width:8px;height:8px;border-radius:50%;flex-shrink:0}.health-legend strong{margin-left:auto}.disk-list,.consumer-list{padding:20px}.disk-list>div,.consumer-list>div{margin-bottom:18px}.disk-list>div:last-child,.consumer-list>div:last-child{margin-bottom:0}.bar-heading{display:flex;justify-content:space-between;gap:12px;font-size:12px;margin-bottom:8px}.bar-heading strong{font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.bar-heading span{white-space:nowrap;font-variant-numeric:tabular-nums}.disk-list small{font-size:11px;display:block;margin-top:6px;color:#71717a}.attention-table :deep(tbody td){height:48px}.attention-clear{padding:24px;display:flex;gap:10px;align-items:center;color:#71717a}.telemetry-expansion{border:1px solid rgba(127,127,127,.2);border-radius:12px;overflow:hidden;font-size:13px}.telemetry-warning{background:rgba(245,158,11,.1)}.agent-secret{display:block;overflow-wrap:anywhere;user-select:all}.telemetry-empty{text-align:center;padding:40px 20px}.telemetry-empty h2{font-size:18px}.telemetry-empty p{font-size:13px;color:#71717a}.body--dark .health-ring>div{background:#1d1d1d}.body--dark .metric-label,.body--dark .metric-cell>small,.body--dark .server-summary span{color:#a1a1aa}@media(max-width:1100px){.server-summary{align-items:flex-start;flex-direction:column}.container-health{gap:16px;padding:20px}.trend-grid,.telemetry-grid{grid-template-columns:1fr}.trend-grid>*+*{border-left:0;border-top:1px solid rgba(127,127,127,.15)}}@media(max-width:650px){.metric-strip{grid-template-columns:1fr 1fr}.metric-cell{border-bottom:1px solid rgba(127,127,127,.15)}.metric-cell:nth-child(2){border-right:0}.telemetry-filters{flex-wrap:wrap}.telemetry-server{width:100%}.telemetry-range{flex:1}.telemetry-contact{align-items:flex-start;flex-direction:column}.server-summary>div:first-child{flex-wrap:wrap}.metric-cell>strong{font-size:24px}}
.telemetry-mobile-card{width:100%;margin:6px 0;overflow-wrap:anywhere}.telemetry-mobile-card dl{display:grid;gap:10px;margin:12px 0 0}.telemetry-mobile-card dt{font-size:12px;color:var(--i7y-muted,#71717a)}.telemetry-mobile-card dd{margin:4px 0 0}.attention-table :deep(.q-table__grid-content),.session-table :deep(.q-table__grid-content){display:block;padding:8px}

@media(max-width:1023px){.telemetry-toolbar{position:static}}
</style>
